<template>
  <v-card outlined class="elevation-2">
    <v-card-title class="indigo darken-1 white--text py-3">
      <v-icon left color="white">mdi-file-document</v-icon>
      Leave Request Details
    </v-card-title>
    <v-card-text class="pa-4">
      <!-- Staff Information -->
      <div class="mb-4 pa-3 blue lighten-5 rounded">
        <v-row dense>
          <v-col cols="12">
            <div
              class="text-caption font-weight-bold grey--text text--darken-2"
            >
              STAFF MEMBER
            </div>
            <h3 class="text-h5 font-weight-bold mt-1">
              {{ requestData.practitionerName }}
            </h3>
          </v-col>
        </v-row>
      </div>

      <v-divider class="my-3"></v-divider>

      <!-- Leave Type, Request Date, Total Days -->
      <v-row
        dense
        align="center"
        justify="space-between"
        no-gutters
        class="mb-3"
      >
        <v-col cols="auto">
          <div
            class="text-caption font-weight-bold grey--text text--darken-2 mb-1"
          >
            LEAVE TYPE
          </div>
          <v-chip
            :color="getLeaveTypeColor(this.requestData.leaveTypeId)"
            text-color="white"
            class="font-weight-bold"
          >
            {{ requestData.leaveCategory }}
          </v-chip>
        </v-col>
        <v-col cols="auto">
          <div
            class="text-caption font-weight-bold grey--text text--darken-2 mb-1"
          >
            REQUEST DATE
          </div>
          <div class="text-body-1 font-weight-medium">
            {{ formatDate(requestData.requestDate) }}
          </div>
        </v-col>
        <v-col cols="auto">
          <div
            class="text-caption font-weight-bold grey--text text--darken-2 mb-1"
          >
            TOTAL DAYS
          </div>
          <div class="text-body-1 font-weight-medium">
            <v-chip
              color="primary"
              text-color="white"
              small
              class="font-weight-bold"
            >
              {{ requestData.days }} days
            </v-chip>
          </div>
        </v-col>
      </v-row>

      <v-divider class="my-2"></v-divider>

      <!-- Leave Dates -->
      <v-row
        dense
        align="center"
        justify="space-between"
        no-gutters
        class="mb-3"
      >
        <v-col cols="auto">
          <div
            class="text-caption font-weight-bold grey--text text--darken-2 mb-1"
          >
            START DATE
          </div>
          <div class="text-body-1 font-weight-medium">
            <v-icon small color="primary">mdi-calendar-start</v-icon>
            {{ formatDate(requestData.startDate) }}
          </div>
        </v-col>
        <v-col cols="auto">
          <div
            class="text-caption font-weight-bold grey--text text--darken-2 mb-1"
          >
            END DATE
          </div>
          <div class="text-body-1 font-weight-medium">
            <v-icon small color="primary">mdi-calendar-end</v-icon>
            {{ formatDate(requestData.endDate) }}
          </div>
        </v-col>
        <v-col cols="auto">
          <div
            class="text-caption font-weight-bold grey--text text--darken-2 mb-1"
          >
            RETURN DATE
          </div>
          <div class="text-body-1 font-weight-medium">
            <v-icon small color="success">mdi-calendar-check</v-icon>
            {{ formatDate(requestData.returnDate) }}
          </div>
        </v-col>
      </v-row>

      <v-divider class="my-2"></v-divider>

      <!-- Acting Supervisor -->
      <v-row dense class="mb-3" v-if="requestData.actingSupervisorName">
        <v-col cols="12">
          <div
            class="text-caption font-weight-bold grey--text text--darken-2 mb-1"
          >
            ACTING STAFF WHEN AWAY
          </div>
          <div class="text-body-1 font-weight-medium">
            <v-icon small color="orange">mdi-account-supervisor</v-icon>
            {{ requestData.actingSupervisorName }}
          </div>
        </v-col>
      </v-row>

      <v-divider
        class="my-2"
        v-if="requestData.actingSupervisorName"
      ></v-divider>

      <!-- Comments -->
      <v-row dense class="mb-3">
        <v-col cols="12">
          <div
            class="text-caption font-weight-bold grey--text text--darken-2 mb-2"
          >
            STAFF COMMENTS
          </div>
          <v-card outlined class="pa-3">
            <p class="text-body-1 font-weight-medium mb-0">
              {{ requestData.comments || "No comments provided" }}
            </p>
          </v-card>
        </v-col>
      </v-row>

      <!-- Supporting Documents -->
      <v-row dense v-if="requestData.supportingDocuments.length > 0">
        <v-col cols="12">
          <div
            class="text-caption font-weight-bold grey--text text--darken-2 mb-2"
          >
            SUPPORTING DOCUMENTS
          </div>
          <v-list dense>
            <v-list-item
              v-for="(doc, index) in requestData.supportingDocuments"
              :key="index"
              @click="downloadDocument(doc)"
            >
              <v-list-item-icon>
                <v-icon color="blue">mdi-file-document</v-icon>
              </v-list-item-icon>
              <v-list-item-content>
                <v-list-item-title class="font-weight-medium">{{
                  doc.title || `Document ${index + 1}`
                }}</v-list-item-title>
                <v-list-item-subtitle class="text-caption">{{
                  doc.contentType
                }}</v-list-item-subtitle>
              </v-list-item-content>
              <v-list-item-action>
                <v-btn icon small>
                  <v-icon small>mdi-download</v-icon>
                </v-btn>
              </v-list-item-action>
            </v-list-item>
          </v-list>
        </v-col>
      </v-row>
      <v-row v-if="requestData.loadingRequest">
        <v-col cols="12" class="text-center py-12">
          <v-progress-circular
            indeterminate
            color="primary"
            size="64"
          ></v-progress-circular>
          <p class="mt-4 text-h6 font-weight-medium">
            Loading leave request details...
          </p>
        </v-col>
      </v-row>
    </v-card-text>
  </v-card>
</template>

<script>
export default {
  name: "LeaveDetailsDisplay",
  props: ["requestId"],
  data() {
    return {
      requestData: {
        loadingRequest: true,
        leaveCategory: "",
        leaveTypeId: "",
        startDate: "",
        endDate: "",
        returnDate: "",
        requestDate: "",
        days: 0,
        comments: "",
        status: "",
        statusDisplay: "",
        actingSupervisorName: "",
        actingSupervisorId: "",
        supportingDocuments: [],
        practitionerName: "",
      },
    };
  },

  methods: {
    async loadLeaveRequest() {
      this.requestData.loadingRequest = true;
      try {
        // Fetch leave request
        let url = `/fhir/Basic/${this.requestId}`;
        let response = await fetch(url);
        let leaverequest = await response.json();
        this.requestId = leaverequest.id;
        // Extract request data
        this.extractRequestData(leaverequest);

        // Load practitioner name
        await this.loadPractitioner(leaverequest);

        // Load acting supervisor (if exists)
        await this.loadActingSupervisor(leaverequest);

        // Load leave category
        await this.loadLeaveCategory(leaverequest);
        this.requestData.loadingRequest = false;
        this.$emit("requestData", this.requestData);
      } catch (error) {
        console.error("Error loading leave request:", error);
        this.showSnackbar("Error loading leave request details", "error");
      }
    },
    extractRequestData(resource) {
      // Extract all extensions
      const getExt = (url, type) => {
        const ext = resource.extension?.find((e) => e.url.includes(url));
        return ext ? ext[type] : null;
      };

      this.requestData.startDate = getExt("start-date", "valueDate");
      this.requestData.endDate = getExt("end-date", "valueDate");
      this.requestData.returnDate = getExt("return-date", "valueDate");
      this.requestData.requestDate = getExt("request-date", "valueDate");
      this.requestData.days = getExt("days", "valueInteger") || 0;
      this.requestData.comments = getExt("comments", "valueString") || "";

      // Status
      const statusCoding = getExt("status", "valueCoding");
      this.requestData.status = statusCoding?.code || "";
      this.requestData.statusDisplay = statusCoding?.display || "";

      // Supporting documents
      const docs = resource.extension?.filter((e) =>
        e.url.includes("supporting-document"),
      );
      this.supportingDocuments = docs?.map((d) => d.valueAttachment) || [];

      // Store practitioner ID
      const practExt = resource.extension?.find((e) =>
        e.url.includes("practitioner"),
      );
      this.practitionerId =
        practExt?.valueReference?.reference?.split("/")[1] || "";

      // Store acting supervisor ID
      const actingExt = resource.extension?.find((e) =>
        e.url.includes("acting-supervisor"),
      );
      this.requestData.actingSupervisorId =
        actingExt?.valueReference?.reference?.split("/")[1] || "";
    },

    async loadPractitioner() {
      if (!this.practitionerId) return;

      try {
        const response = await fetch(
          `/fhir/Practitioner/${this.practitionerId}`,
        );
        const practitioner = await response.json();
        const name = practitioner.name?.[0];
        this.requestData.practitionerName = name
          ? `${name.given?.join(" ")} ${name.family}`.trim()
          : "Unknown";
      } catch (error) {
        console.error("Error loading practitioner:", error);
      }
    },

    async loadActingSupervisor() {
      if (!this.requestData.actingSupervisorId) return;

      try {
        const response = await fetch(
          `/fhir/Practitioner/${this.requestData.actingSupervisorId}`,
        );
        const supervisor = await response.json();
        const name = supervisor.name?.[0];
        this.requestData.actingSupervisorName = name
          ? `${name.given?.join(" ")} ${name.family}`.trim()
          : "Unknown";
      } catch (error) {
        console.error("Error loading acting supervisor:", error);
      }
    },

    async loadLeaveCategory(resource) {
      const catExt = resource.extension?.find((e) =>
        e.url.includes("leave-category"),
      );
      const categoryId = catExt?.valueReference?.reference?.split("/")[1];

      if (!categoryId) return;

      try {
        const response = await fetch(`/fhir/Basic/${categoryId}`);
        const category = await response.json();

        this.requestData.leaveTypeId = categoryId;

        const nameExt = category.extension?.find((e) =>
          e.url.includes("ihris-basic-name"),
        );
        this.requestData.leaveCategory = nameExt?.valueString || "Unknown";
      } catch (error) {
        console.error("Error loading leave category:", error);
      }
    },
    formatDate(dateString) {
      if (!dateString) return "N/A";
      const date = new Date(dateString);
      return date.toLocaleDateString("en-US", {
        year: "numeric",
        month: "short",
        day: "numeric",
      });
    },

    getLeaveTypeColor(leaveTypeId) {
      const typeMap = {
        annual: "blue",
        maternity: "pink",
        paternity: "indigo",
        compassionate: "purple",
        unpaid: "orange",
        sick: "red",
        stillborn: "deep-purple",
        bonding: "teal",
        study: "green",
      };
      return typeMap[leaveTypeId] || "grey";
    },

    downloadDocument(doc) {
      // Implement document download
      if (doc.data && doc.contentType) {
        const blob = this.base64toBlob(doc.data, doc.contentType);
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = doc.title || "document";
        link.click();
        window.URL.revokeObjectURL(url);
      }
    },

    base64toBlob(base64Data, contentType) {
      contentType = contentType || "";
      const sliceSize = 1024;
      const byteCharacters = atob(base64Data);
      const bytesLength = byteCharacters.length;
      const slicesCount = Math.ceil(bytesLength / sliceSize);
      const byteArrays = new Array(slicesCount);

      for (let sliceIndex = 0; sliceIndex < slicesCount; ++sliceIndex) {
        const begin = sliceIndex * sliceSize;
        const end = Math.min(begin + sliceSize, bytesLength);

        const bytes = new Array(end - begin);
        for (let offset = begin, i = 0; offset < end; ++i, ++offset) {
          bytes[i] = byteCharacters[offset].charCodeAt(0);
        }
        byteArrays[sliceIndex] = new Uint8Array(bytes);
      }
      return new Blob(byteArrays, { type: contentType });
    },
  },
  created() {
    this.loadLeaveRequest();
  },
};
</script>

